{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    # Validate
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('Missing fields')
        if s['minimum'] < 0 or s['capacity'] < s['minimum']:
            raise ValueError('Invalid min/cap')
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of range')
    alloc = [s['minimum'] for s in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_imp = None
        best_pos = None
        for i, s in enumerate(segments):
            if alloc[i] >= s['capacity']:
                continue
            imp = s['importance']
            pos = alloc[i] + 1
            if best_idx == -1:
                best_idx = i
                best_imp = imp
                best_pos = pos
            else:
                # compare best_imp/best_pos vs imp/pos
                left = best_imp * pos
                right = imp * best_pos
                if right > left or (right == left and i < best_idx):
                    best_idx = i
                    best_imp = imp
                    best_pos = pos
        if best_idx == -1:
            raise ValueError('Cannot allocate')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(len(segments))}
    total = sum(alloc)
    if total != budget:
        raise ValueError('Total mismatch')
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
